create or replace function platform.enqueue_automation_for_event(p_event_id uuid) returns integer language plpgsql security definer set search_path=platform,public as $$ declare e platform.system_events;a record;n integer:=0;begin select * into e from platform.system_events where id=p_event_id;if not found then raise exception 'EVENT_NOT_FOUND';end if;for a in select id from platform.automations where status='active' and (trigger->>'event_type')=e.event_type loop insert into platform.automation_runs(automation_id,event_id,status,current_step,context) values(a.id,e.id,'queued',0,coalesce(e.payload,'{}')) on conflict do nothing;n:=n+1;end loop;return n;end $$;
revoke all on function platform.enqueue_automation_for_event(uuid) from public;grant execute on function platform.enqueue_automation_for_event(uuid) to authenticated;
create or replace function ai.generate_product_recommendations(p_customer_id uuid default null,p_product_id uuid default null) returns integer language plpgsql security definer set search_path=ai,customer,catalog,public as $$ declare a uuid:=auth.uid();c uuid;n integer:=0;r record;begin if a is null then raise exception 'AUTH_REQUIRED';end if;select id into c from customer.customers where auth_user_id=a limit 1;if p_customer_id is not null and p_customer_id<>c and not platform.has_permission(a,'orders.read') then raise exception 'FORBIDDEN';end if;c:=coalesce(p_customer_id,c);if p_product_id is not null then for r in select pr.related_product_id,pr.score from catalog.product_relations pr where pr.product_id=p_product_id order by pr.score desc nulls last,pr.sort_order limit 12 loop insert into ai.recommendations(type,title,evidence,confidence,status) values('product_related','Recommended product',jsonb_build_object('customer_id',c,'source_product_id',p_product_id,'related_product_id',r.related_product_id),least(0.99,greatest(0.1,coalesce(r.score,0.5))),'active');n:=n+1;end loop;else for r in select s.product_variant_id,s.score from customer.buy_again_signals s where s.customer_id=c order by s.score desc limit 12 loop insert into ai.recommendations(type,title,evidence,confidence,status) values('buy_again','Buy again',jsonb_build_object('customer_id',c,'product_variant_id',r.product_variant_id),least(0.99,greatest(0.1,r.score)),'active');n:=n+1;end loop;end if;return n;end $$;
revoke all on function ai.generate_product_recommendations(uuid,uuid) from public;grant execute on function ai.generate_product_recommendations(uuid,uuid) to authenticated;